// Datos que extrajo la IA
const ia = $('IA – Clasificar y extraer').first().json.output;

// Busca un campo por el inicio de su nombre (evita problemas con tildes y símbolos)
const campo = (obj, prefijo) => obj[Object.keys(obj).find(k => k.startsWith(prefijo))];

// Buscar producto y material en lo que leímos de Notion
const producto = $('Notion – Leer catálogo').all().find(p => p.json.property_producto === ia.producto);
const material = $('Notion – Leer materiales').all().find(m => m.json.property_material === ia.material);

if (!producto) throw new Error(`Producto no encontrado en catálogo: ${ia.producto}`);
if (!material) throw new Error(`Material no encontrado: ${ia.material}`);

const precioBase = campo(producto.json, 'property_precio');
const unidad = campo(producto.json, 'property_unidad');
const plazo = campo(producto.json, 'property_plazo');
const recargo = campo(material.json, 'property_recargo') || 0;

// Por metro lineal se multiplica por la medida; por unidad, no
const factorMedida = unidad === 'Por metro lineal' ? ia.medida_m : 1;
const cantidad = ia.cantidad || 1;

const total = Math.round(precioBase * factorMedida * (1 + recargo) * cantidad);

return [{
  json: {
    producto: ia.producto,
    producto_id: producto.json.id,
    material: ia.material,
    material_id: material.json.id,
    medida_m: ia.medida_m,
    cantidad,
    precio_base: precioBase,
    recargo_material: recargo,
    unidad_precio: unidad,
    plazo_dias: plazo,
    total
  }
}];

